function render() {
  // 清掉旧题目, 保留顶栏
  widgets.forEach(function (w) { if (w.node && w.node.parentNode) w.node.parentNode.removeChild(w.node); });
  widgets = [];
  state.values.quiz = {};
  var anchor = bar;
  QUIZ.forEach(function (item, qi) {
    var order = shuffle(items_indices(item.options.length));
    var node = document.createElement("div");
    node.className = "q";

    var stem = document.createElement("p");
    stem.className = "stem";
    var qn = document.createElement("span");
    qn.className = "qn";
    qn.textContent = String(qi + 1) + ".";
    stem.appendChild(qn);
    stem.appendChild(document.createTextNode(item.stem));
    node.appendChild(stem);

    var fs = document.createElement("fieldset");
    var lg = document.createElement("legend");
    lg.textContent = "第 " + (qi + 1) + " 题, 选择一个答案";
    fs.appendChild(lg);

    var fb = document.createElement("div");
    fb.className = "fb";
    fb.setAttribute("role", "status");
    fb.setAttribute("aria-live", "polite");

    var groupName = "q_" + item.id + "_" + qi;
    var optNodes = [];

    order.forEach(function (origIdx, pos) {
      var text = item.options[origIdx];
      var isRight = origIdx === item.answer;
      var id = groupName + "_" + pos;

      var lab = document.createElement("label");
      lab.className = "opt";
      lab.setAttribute("for", id);

      var input = document.createElement("input");
      input.type = "radio";
      input.name = groupName;
      input.id = id;
      input.value = String(origIdx);

      var mark = document.createElement("span");
      mark.className = "mark";
      mark.textContent = labels[pos];

      var span = document.createElement("span");
      span.textContent = text;

      lab.appendChild(input);
      lab.appendChild(mark);
      lab.appendChild(span);

      var optNode = { lab: lab, input: input, right: isRight, text: text };
      optNodes.push(optNode);

      input.addEventListener("change", function () {
        var chosenRight = input.value === String(item.answer);
        state.values.quiz[item.id] = { 选择: text, 正确: chosenRight };

        optNodes.forEach(function (o) {
          o.lab.classList.remove("correct", "wrong");
          if (o.right) o.lab.classList.add("correct");
        });
        if (!chosenRight) lab.classList.add("wrong");

        fb.textContent = "";
        var verdict = document.createElement("b");
        verdict.textContent = chosenRight ? "答对了. " : "答错了. ";
        fb.appendChild(verdict);
        if (!chosenRight) {
          var rightText = item.options[item.answer];
          fb.appendChild(document.createTextNode("正确选项是 \u201C" + rightText + "\u201D. "));
        }
        fb.appendChild(document.createTextNode(item.why));
        fb.classList.add("show");

        updateScore();
      });

      fs.appendChild(lab);
    });

    fs.appendChild(fb);
    node.appendChild(fs);

    anchor.parentNode.insertBefore(node, anchor.nextSibling);
    anchor = node;

    widgets.push({ node: node, fb: fb, optNodes: optNodes });
  });

  updateScore();
}
